{
  "findings": [
    {
      "check_id": "CKV_AZURE_25",
      "title": "Threat Detection types are not set to 'All'",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The `disabled_alerts` list explicitly disables critical security alerts such as 'Sql_Injection' and 'Data_Exfiltration', violating the requirement that threat detection types should be set to 'All' (i.e., no alerts disabled)."
    },
    {
      "check_id": "CKV_AZURE_26",
      "title": "'Send Alerts To' is not enabled for MSSQL servers",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The resource lacks the `email_account_admins` attribute or specific email addresses in an alert action group configuration, meaning security alerts are not being sent to designated administrators."
    },
    {
      "check_id": "CKV_AZURE_27",
      "title": "'Email service and co-administrators' is not Enabled for MSSQL servers",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The `email_account_admins` argument is missing from the resource definition. It defaults to false, preventing Azure from sending security alerts to subscription co-administrators."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  # CKV_AZURE_25: Remove disabled alerts to ensure all threat detection types are active\n  disabled_alerts = []\n  retention_days = 20\n  # CKV_AZURE_26 & CKV_AZURE_27: Enable emailing account admins for alerts\n  email_account_admins = true\n}",
  "fix_summary": "Removed entries from `disabled_alerts` to enable all threat detection types (CKV_AZURE_25). Added `email_account_admins = true` to ensure security alerts are sent to subscription co-administrators (CKV_AZURE_26/27)."
}
